primaryQuery:
run: order_items extend {
  join_one: inventory_items is inventory_items
    on inventory_item_id = inventory_items.id
} -> {
  aggregate:
    total_cost is inventory_items.cost.sum()
    items_sold is count()
} -> {
  select:
    total_cost
    items_sold
    avg_cost_per_item_sold is round(total_cost / items_sold, 4)
}

verifyQuery:
run: inventory_items extend {
  join_one: oi is order_items on id = oi.inventory_item_id
} -> {
  where: oi.id is not null
  aggregate:
    total_cost is cost.sum()
    items_sold is count()
    avg_cost_per_item_sold is round(cost.avg(), 4)
}
